+const END_FRAG = /* glsl */ `
+uniform sampler2D uPlate;
+uniform vec4 uPjPost;
+uniform vec2 uPjRes;
+uniform float uAway;
+uniform vec4 uE;             // x glow point height (fraction of r, < 0 below the axis), y ring shrink per ring, z core size, w halo size
