+  vec3 cLip = vec3(1.0, 0.80, 0.42);
+  vec3 cGr = vec3(0.45, 0.14, 0.12);
+  vec3 ring = mix(cBand, cLip, lip);
+  ring = mix(ring, cGr, groove * 0.85);
+  vec3 col = mix(vec3(0.92, 0.50, 0.24), ring, rk);
