      mt.colorSpace = THREE.NoColorSpace; mt.flipY = false; mt.wrapS = THREE.RepeatWrapping; mt.wrapT = THREE.ClampToEdgeWrapping;
      mt.minFilter = THREE.LinearMipmapLinearFilter; mt.anisotropy = 8;
